"use client"

import { ChevronDownIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button, LinkButton } from "@/components/ui/button"
import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible"
import { Skeleton } from "@/components/ui/skeleton"

type FieldRow = { label: string; value?: string }
type Group = { title: string; fields: FieldRow[]; collapsed?: boolean }

/**
 * Record detail: status badge, grouped label/value fields (each group a
 * Disclosure), a loading skeleton and record actions.
 */
export default function RecordDetail({
  title = "Invoice INV-0042",
  status = "Paid",
  loading = false,
  groups = [
    { title: "Summary", fields: [{ label: "Customer", value: "Example Co." }, { label: "Amount", value: "$1,200.00" }, { label: "Issued", value: "Oct 2, 2026" }] },
    { title: "Payment", fields: [{ label: "Method", value: "Card" }, { label: "Reference", value: "PAY-9813" }], collapsed: true },
  ],
  actions = [{ id: "download", label: "Download" }],
  link,
  onAction,
}: {
  title?: string
  status?: string
  loading?: boolean
  groups?: Group[]
  actions?: { id: string; label: string }[]
  link?: { label: string; href: string }
  onAction?: (id: string) => void
}) {
  return (
    <section data-slot="record-detail" aria-busy={loading || undefined} className="py-8">
      <div className="mx-auto max-w-3xl px-6">
        <div className="flex flex-wrap items-center justify-between gap-4">
          <div className="flex items-center gap-2">
            <h2 className="font-heading text-xl font-semibold tracking-tight">{title}</h2>
            {status && <Badge variant="secondary">{status}</Badge>}
          </div>
          <div className="flex gap-2">
            {link && (
              <LinkButton href={link.href} variant="ghost">
                {link.label}
              </LinkButton>
            )}
            {actions.map((a) => (
              <Button key={a.id} variant="outline" onPress={() => onAction?.(a.id)}>
                {a.label}
              </Button>
            ))}
          </div>
        </div>
        <div className="mt-6 divide-y divide-border rounded-lg border border-border">
          {groups.map((g) => (
            <Collapsible key={g.title} defaultExpanded={!g.collapsed}>
              <CollapsibleTrigger className="group flex w-full items-center justify-between px-4 py-3 text-sm font-medium">
                {g.title}
                <ChevronDownIcon className="size-4 text-muted-foreground transition-transform group-aria-expanded:rotate-180" />
              </CollapsibleTrigger>
              <CollapsibleContent>
                <dl className="grid gap-x-6 gap-y-3 px-4 pb-4 sm:grid-cols-2">
                  {g.fields.map((f) => (
                    <div key={f.label} className="space-y-1">
                      <dt className="text-xs text-muted-foreground">{f.label}</dt>
                      <dd className="text-sm">{loading ? <Skeleton className="h-4 w-32" /> : (f.value ?? "None")}</dd>
                    </div>
                  ))}
                </dl>
              </CollapsibleContent>
            </Collapsible>
          ))}
        </div>
      </div>
    </section>
  )
}
